/// link-card: Link preview
private struct LinkCardExample0: View {
    private let url = URL(string: "https://example.com/guides/first-week") ?? URL(fileURLWithPath: "/")
    private let picture: Image = {
        let width = 1200, height = 630
        guard let context = CGContext(
            data: nil, width: width, height: height, bitsPerComponent: 8, bytesPerRow: 0,
            space: CGColorSpaceCreateDeviceRGB(), bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue
        ) else { return Image(systemName: "photo") }
        // Core Graphics counts up from the bottom: flip it so the picture is drawn from the top left.
        context.translateBy(x: 0, y: CGFloat(height))
        context.scaleBy(x: 1, y: -1)
        context.setFillColor(red: 0.86, green: 0.86, blue: 0.86, alpha: 1)
        context.fill(CGRect(x: 0, y: 0, width: width, height: height))
        context.setFillColor(red: 0.75, green: 0.75, blue: 0.75, alpha: 1)
        context.fillEllipse(in: CGRect(x: 800, y: 80, width: 240, height: 240))
        context.setFillColor(red: 0.67, green: 0.67, blue: 0.67, alpha: 1)
        context.move(to: CGPoint(x: 0, y: 630))
        context.addLine(to: CGPoint(x: 400, y: 180))
        context.addLine(to: CGPoint(x: 700, y: 480))
        context.addLine(to: CGPoint(x: 880, y: 330))
        context.addLine(to: CGPoint(x: 1200, y: 630))
        context.fillPath()
        guard let picture = context.makeImage() else { return Image(systemName: "photo") }
        return Image(decorative: picture, scale: 1)
    }()

    var body: some View {
        MonarchLinkCard(
            "Your first week: a practical guide",
            url: url,
            description: "What to set up, who to meet and where to find things in your first five days.",
            siteName: "Example Guides",
            image: picture,
            imageSize: CGSize(width: 1200, height: 630)
        )
    }
}

