/// mention-picker: Suggestions while typing a mention
private struct MentionPickerExample0: View {
    @State private var text = "Thanks @Ana Lopez, looping in @be"
    @State private var query: MonarchMentionQuery?
    private let people = [
        MonarchMentionItem(id: "u_ben", label: "Ben Okafor", detail: "Engineering"),
    ]
    @Environment(\.monarchTheme) private var theme

    var body: some View {
        VStack(alignment: .leading, spacing: theme.spacing.space2) {
            MonarchTextField("Comment", text: $text, helper: "Type @ for people or # for channels.", axis: .vertical, lineLimit: 3...6)
            // The suggestions float under the field, on a raised card.
            MonarchMentionPicker(query, items: people) { item in
                guard let query else { return }
                text = query.replacing(in: text, with: "@\(item.label)")
            }
            .clipShape(RoundedRectangle(cornerRadius: theme.radius.md, style: .continuous))
            .monarchElevation(.presented, fill: \.bgRaised, in: RoundedRectangle(cornerRadius: theme.radius.md, style: .continuous))
        }
        .onChange(of: text, initial: true) { _, new in
            query = MonarchMentionQuery.find(in: new)
