                    inviteRow
                    Text("People with access").monarchTextStyle(.bodyStrong)
                    peopleRows
                    Text("General access").monarchTextStyle(.bodyStrong)
                    generalAccess
                }
            } footer: {
                EmptyView()
            }
    }
}

