    private static let now = Date(timeIntervalSinceReferenceDate: 800_000_000)
    private static let people = ["Alex Morgan", "Sam Lee", "Riley Chen"]
    private static let lines = ["Morning! Is the release still on for Thursday?", "Yes, the checklist is nearly done.", "I will update the notes after lunch.", "Can someone review the new onboarding copy?", "Looks good to me.", "Shipping the fix now."]
    private static func message(_ n: Int) -> ChatMessage {
        ChatMessage(
            id: "msg-\(n)",
            time: now.addingTimeInterval(TimeInterval(n - (1500 + 500)) * 420),
            authorID: people[(n / 3) % people.count],
            text: "\(lines[n % lines.count]) (#\(n + 1))"
        )
    }
    @State private var messages = (1500..<(1500 + 500)).map { Self.message($0) }
    @State private var scrollTo: String?

    var body: some View {
        VStack(alignment: .leading, spacing: MonarchTokens.Space.space2) {
            HStack(spacing: MonarchTokens.Space.space2) {
                MonarchButton("Receive a message", variant: .secondary, size: .sm) {
                    messages.append(Self.message(messages.count + 1500))
                }
                MonarchButton("Go to message 1601", variant: .ghost, size: .sm) { scrollTo = "msg-1600" }
            }
            MonarchVirtualMessageList(
                messages,
                firstUnreadID: "msg-1995",
                scrollToID: scrollTo,
                hasOlder: true,
                now: Self.now,
                onLoadOlder: {},
                row: { message, context in
                    MonarchMessageRow(
                        MonarchMessageRowAuthor(message.authorID ?? ""),
                        time: message.time,
                        now: Self.now,
                        isGrouped: context.isGrouped
                    ) {
                        Text(message.text)
                    }
                }
            )
            .frame(height: 720)
        }
        .environment(\.locale, Locale(identifier: "en-GB"))
    }
}

/// virtual-message-list: An empty conversation shows its header
private struct VirtualMessageListExample1: View {
    struct ChatMessage: MonarchVirtualMessageListItem {
        let id: Int
        let time: Date
        let authorID: String?
        let text: String
    }
    private let now = Date(timeIntervalSinceReferenceDate: 800_000_000)
    @State private var messages: [ChatMessage] = (0..<12).map { (index: Int) -> ChatMessage in
        ChatMessage(
            id: index,
            time: Date(timeIntervalSinceReferenceDate: 800_000_000).addingTimeInterval(TimeInterval((index - 12) * 120)),
            authorID: index % 3 == 0 ? "ben" : "ana",
            text: "Message \(index)"
        )
    }

    var body: some View {
        MonarchVirtualMessageList(
            [ChatMessage](),
            header: { Text("This is the start of your conversation with Ben.").padding() },
            footer: { EmptyView() },
            row: { message, _ in Text(message.text) }
        )
        .frame(height: 240)
    }
}
